			String turkishLowerInputLabel = "ISTANBUL CASE FOLDING FOLLOWS THE TURKISH DEFAULT LOCALE";
			String turkishUpperInputLabel = "istanbul case folding follows the turkish default locale";
			String turkishLowerLabel = turkishLowerInputLabel.toLowerCase(turkishLocale);
			String turkishUpperLabel = turkishUpperInputLabel.toUpperCase(turkishLocale);
			Value turkishLowerInput = store.createLiteral(turkishLowerInputLabel);
			Value turkishLowerResult = store.createLiteral(turkishLowerLabel);
			Value turkishUpperInput = store.createLiteral(turkishUpperInputLabel);
			Value turkishUpperResult = store.createLiteral(turkishUpperLabel);
			Value languageAndDirection = store.createLiteral("MiXeD directional language label", "en",
					Literal.BaseDirection.RTL);
