				LmdbNativeValueCodec.DecodedValue turkishLowerInputValue = codec.decodeAssured(turkishLowerInputId);
				LmdbNativeValueCodec.DecodedValue turkishUpperInputValue = codec.decodeAssured(turkishUpperInputId);
				assertMatchesGenericCaseFold(true, turkishLowerInputValue);
				assertMatchesGenericCaseFold(false, turkishUpperInputValue);
